head.script:
scwin.onpageload = function () {
    dlt_spin.setJSON([
        { "txt" : "Row 0", "spinBasic" : "10", "spinEmbedded" : "10" },
        { "txt" : "Row 1", "spinBasic" : "10", "spinEmbedded" : "10" },
        { "txt" : "Row 2", "spinBasic" : "10", "spinEmbedded" : "10" },
        { "txt" : "Row 3", "spinBasic" : "10", "spinEmbedded" : "10" }
    ]);
};

// spinBasic (embeddedInput 미설정) customFormatter
scwin.spinBasic_customFormatter = function (rowIndex, columnIndex) {
    scwin.setReturnValue("[spinBasic] rowIndex=" + rowIndex + ", columnIndex=" + columnIndex + " (기대 " + grd_spin.getColumnIndex("spinBasic") + ")");
};

// spinEmbedded (embeddedInput=true) customFormatter
scwin.spinEmbedded_customFormatter = function (rowIndex, columnIndex) {
    scwin.setReturnValue("[spinEmbedded] rowIndex=" + rowIndex + ", columnIndex=" + columnIndex + " (기대 " + grd_spin.getColumnIndex("spinEmbedded") + ")");
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
